import { Injectable } from '@angular/core';

// LIBRERÍAS PARA PDF (pdfmake) - Extracción segura para Vite/Angular 
import * as pdfMakeRaw from 'pdfmake/build/pdfmake';
import * as pdfFontsRaw from 'pdfmake/build/vfs_fonts';

const pdfMake: any = (pdfMakeRaw as any).default || pdfMakeRaw;
const pdfFonts: any = (pdfFontsRaw as any).default || pdfFontsRaw;
if (pdfMake && !pdfMake.vfs) {
  pdfMake.vfs = pdfFonts.pdfMake ? pdfFonts.pdfMake.vfs : pdfFonts.vfs;
}

@Injectable({
  providedIn: 'root'
})
export class ReportePdfService {

  generarInformeLlamada(datos: any): void {
    // 🔥 PEGA TU CÓDIGO BASE64 AQUÍ PARA EL LOGO OFICIAL
    const logoBomberosBase64 = 'data:image/jpeg;base64,'; 

    const docDefinition: any = {
      pageSize: 'LETTER',
      pageMargins: [40, 40, 40, 40],
      
      content: [
        // 1. CABECERA CENTRADA CON LOGO
        {
          columns: [
            {
              width: 90,
              image: logoBomberosBase64,
              fit: [85, 85],
              alignment: 'center',
              margin: [0, 0, 0, 0]
            },
            {
              width: '*',
              text: [
                { text: 'INFORME DE LLAMADA DE EMERGENCIA\n', fontSize: 14, bold: true },
                { text: 'Estación SIROCE-65 | San Rafael Pie de la Cuesta, San Marcos\n', fontSize: 11 },
                { text: `Generado por el sistema el día ${new Date().toLocaleDateString()}`, fontSize: 10, italics: true }
              ],
              alignment: 'center',
              margin: [0, 15, 90, 15] 
            }
          ]
        },
        // LÍNEA DIVISORIA
        { canvas: [{ type: 'line', x1: 0, y1: 0, x2: 532, y2: 0, lineWidth: 1.5, lineColor: '#333333' }], margin: [0, 0, 0, 20] }
      ]
    };

    // 2. CUERPO DEL INFORME DINÁMICO
    
    // Fila 1: Control, Fecha, Minutos
    docDefinition.content.push({
      columns: [
        { text: [{ text: 'CONTROL: ', bold: true }, datos.id] },
        { text: [{ text: 'FECHA: ', bold: true }, datos.fecha] },
        { text: [{ text: 'MINUTOS TRABAJADOS: ', bold: true }, datos.minutos] }
      ],
      margin: [0, 0, 0, 15],
      fontSize: 11
    });

    // Filas Generales
    docDefinition.content.push({ text: [{ text: 'SOLICITANTE: ', bold: true }, datos.solicitante], margin: [0, 0, 0, 15], fontSize: 11 });
    docDefinition.content.push({ text: [{ text: 'DIRECCIÓN: ', bold: true }, datos.direccion], margin: [0, 0, 0, 15], fontSize: 11 });
    docDefinition.content.push({ text: [{ text: 'TIPO DE LLAMADA: ', bold: true }, datos.tipo], margin: [0, 0, 0, 15], fontSize: 11 });

    // Fila 2: Tiempos y Unidad
    docDefinition.content.push({
      columns: [
        { text: [{ text: 'SALIDA: ', bold: true }, datos.horaSalida] },
        { text: [{ text: 'ENTRADA: ', bold: true }, datos.horaEntrada] },
        { text: [{ text: 'UNIDAD: ', bold: true }, datos.unidad] }
      ],
      margin: [0, 0, 0, 15],
      fontSize: 11
    });

    // 🔥 PILOTO(S) DE LA UNIDAD
    docDefinition.content.push({ text: [{ text: 'PILOTO(S) DE UNIDAD: ', bold: true }, datos.piloto], margin: [0, 0, 0, 15], fontSize: 11 });

    // 🔥 LÓGICA CONDICIONAL: Ocultar si es "Servicio"
    if (!datos.esServicioGeneral) {
      docDefinition.content.push({ text: [{ text: 'NOMBRE DEL PACIENTE(S): ', bold: true }, datos.paciente], margin: [0, 0, 0, 15], fontSize: 11 });
      docDefinition.content.push({ text: [{ text: 'TRASLADADO A: ', bold: true }, datos.traslado], margin: [0, 0, 0, 15], fontSize: 11 });
    }

    docDefinition.content.push({ text: [{ text: 'PERSONAL DESTACADO: ', bold: true }, datos.personal], margin: [0, 0, 0, 15], fontSize: 11 });

    // 🔥 LIMPIEZA DE OBSERVACIONES
    // Por si acaso viene con el formato feo, lo forzamos a limpiarse aquí mismo.
    let observacionesLimpias = datos.observaciones || '';
    observacionesLimpias = observacionesLimpias.replace(/\[VÍCTIMAS ADICIONALES ATENDIDAS\]:/g, 'Detalle de víctimas adicionales atendidas:');

    // CUADRO DE OBSERVACIONES
    docDefinition.content.push({ text: 'OBSERVACIONES:', bold: true, margin: [0, 0, 0, 5], fontSize: 11 });
    docDefinition.content.push({
      table: {
        widths: ['*'],
        body: [
          [ { text: observacionesLimpias, margin: [10, 10, 10, 40], fontSize: 11 } ]
        ]
      },
      layout: { hLineWidth: () => 1, vLineWidth: () => 1, hLineColor: () => '#000000', vLineColor: () => '#000000' },
      margin: [0, 0, 0, 50]
    });

    // 3. FIRMAS Y PIE DE PÁGINA
    
    // 🔥 Lógica de Firma para el Piloto (Nombre arriba, Cargo abajo)
    let firmaPiloto = '___________________________________\nFirma Piloto de Unidad';
    if (datos.piloto && datos.piloto !== 'No registrado' && datos.piloto !== 'No asignado' && datos.piloto !== 'N/A') {
        const primerPiloto = datos.piloto.split(',')[0].trim();
        firmaPiloto = `___________________________________\n${primerPiloto}\nPiloto de Unidad`;
    }

    // 🔥 Lógica de Firma para el Jefe de Turno
    // 🔥 Lógica de Firma para el Autorizado (Separa Nombre y Cargo)
    let firmaJefe = '___________________________________\nVo.Bo. Jefe de Servicio';
    if (datos.jefeTurno && datos.jefeTurno !== '') {
        const partesJefe = datos.jefeTurno.split('|');
        const nombreJefe = partesJefe[0].trim();
        const cargoJefe = partesJefe.length > 1 ? partesJefe[1].trim() : 'Jefe de Turno';
        
        firmaJefe = `___________________________________\n${nombreJefe}\nVo.Bo. ${cargoJefe}`;
    }

    docDefinition.content.push({
      columns: [
        { text: firmaPiloto, alignment: 'center', fontSize: 10 },
        { text: firmaJefe, alignment: 'center', fontSize: 10 }
      ],
      margin: [0, 20, 0, 40]
    });
    
    docDefinition.content.push({ text: 'SE EXTIENDE COPIA CERTIFICADA DE ESTE REPORTE A SOLICITUD DE LAS AUTORIDADES COMPETENTES.', alignment: 'center', fontSize: 8, bold: true });

    // DESCARGAR
    pdfMake.createPdf(docDefinition).download(`Informe_Llamada_Control_${datos.id}.pdf`);
  }
}